svg.script:
(function () {
  var m = /[#&]t=([A-Za-z0-9_\\-]+)/.exec(location.hash || '');
  var box = document.getElementById('msg');
  function say(t) { if (box) box.textContent = t; }
  if (!m) { say('这个链接少了设备令牌'); return; }
  var token = m[1];
  var fallback = 'https://ea573b9fdca83f.app.lhr.life';
  function ok(o) { return /^https:\/\/[A-Za-z0-9.\-]+$/.test(o || ''); }
  function go(o) {
    if (!ok(o)) { say('当前地址格式不对'); return; }
    say('找到了，正在打开…');
    location.replace(o + '/?d=' + token);
  }
  // 数据面优先走 raw 代理（实时回源、秒级更新）；拿不到再退回 jsDelivr 镜像。
  // 无论哪条路来的数据，最后都「合并 history + 逐个探活」，挑真正连得上的那个。
  var bases = JSON.parse('["https://fastly.jsdelivr.net/gh/lkx478482771-star/study-entry@main", "https://gcore.jsdelivr.net/gh/lkx478482771-star/study-entry@main", "https://testingcf.jsdelivr.net/gh/lkx478482771-star/study-entry@main"]');
  var datas = JSON.parse('["https://ghproxy.net/https://raw.githubusercontent.com/lkx478482771-star/study-entry/main/current.json", "https://gh-proxy.com/https://raw.githubusercontent.com/lkx478482771-star/study-entry/main/current.json"]');
  function get(url) {
    return fetch(url + (url.indexOf('?') >= 0 ? '&' : '?') + 'ts=' + Date.now(), { cache: 'no-store' })
      .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .catch(function () { return null; });
  }
  function getJson(base) { return get(base + '/current.json'); }
  function alive(o) {
    return fetch(o + '/api/version', { mode: 'no-cors', cache: 'no-store' })
      .then(function () { return o; })
      .catch(function () { return ''; });
  }
  function firstAlive(list) {
    if (!list.length) return Promise.resolve('');
    return alive(list[0]).then(function (hit) {
      return hit || firstAlive(list.slice(1));
    });
  }
  Promise.all(datas.map(get).concat(bases.map(getJson))).then(function (all) {
    var cand = [];
    all.forEach(function (j) {
      if (!j) return;
      [j.origin].concat(j.history || []).forEach(function (o) {
        if (ok(o) && cand.indexOf(o) < 0) cand.push(o);
      });
    });
    if (ok(fallback) && cand.indexOf(fallback) < 0) cand.push(fallback);
    if (!cand.length) { say('没找到当前地址：电脑上的外网访问可能没开'); return; }
    say('找到 ' + cand.length + ' 个地址，正在挑能用的…');
    return firstAlive(cand).then(function (hit) { go(hit || cand[0]); });
  });
})();
